INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124905, 'spa', 'columna de nube o fuego', 'La columna teofánica de nube de día y de fuego de noche en la que Dios guiaba y protegía a Israel durante el éxodo. Aparece por primera vez en Éx 13:21-22, esta columna divina conduce al pueblo, se interpone entre ellos y el ejército de Faraón (Éx 14:19, 24) y desciende a la tienda del encuentro cuando Dios habla con Moisés (Éx 33:9-10; Nm 12:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124933, 'spa', 'Amón (nombre propio)', 'Nombre propio que identifica al pueblo y territorio de los amonitas, descendientes de Ben-Amí, hijo de Lot (Gn 19:38). Aparece casi exclusivamente en la frase בְּנֵי עַמּוֹן (''hijos de Amón''). Central en los relatos de conflicto territorial al este del Jordán —las campañas de Jefté (Jue 10-12), las guerras de David (2 S 10-12)— y en los oráculos de juicio profético (Jer 49:1-6; Ez 25:1-7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124935, 'spa', 'Designación gentilicia para personas pertenecientes a la nación de Amón, al este', 'Designación gentilicia para personas pertenecientes a la nación de Amón, al este del Jordán. El término funciona tanto como adjetivo (''mujeres amonitas'', 1 Re 11:1; Neh 13:23) como sustantivo (''el amonita'', 1 Sam 11:1; Neh 2:10). Los textos legales prohíben a los amonitas entrar en la asamblea israelita (Dt 23:3; Neh 13:1), mientras que los textos narrativos presentan a amonitas individuales como Nahas (1 Sam 11:1), Naama (1 Re 14:21) y Tobías (Neh 2:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124944, 'spa', 'Mujer amonita', 'Forma femenina del gentilicio amonita, que designa a mujeres originarias de Amón. Los cuatro usos (1 Re 14:21, 31; 2 Cr 12:13; 24:26) se refieren a Naamá, madre de Roboam, destacando su origen extranjero. La repetición en textos paralelos (Reyes y Crónicas) evidencia una terminología estandarizada para identificar la etnicidad de las madres reales, con implicaciones teológicas sobre la influencia foránea en la monarquía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124945, 'spa', 'Amós (nombre propio)', 'Nombre propio del profeta Amós (עָמוֹס), pastor y cultivador de higos silvestres de Tecoa en Judá (Am 7:14), activo alrededor del 760-750 a.C. Confrontó al sacerdote Amasías en Betel (Am 7:10-12) y pronunció oráculos que enfatizan la justicia y la rectitud. El nombre se translitéra de manera consistente en todas las tradiciones: ''Amós'' en español, francés y alemán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124947, 'spa', 'Amiel (nombre propio)', 'Nombre propio masculino que significa ''mi pariente es Dios'', aplicado a cuatro figuras del AT. El más prominente narrativamente es el padre de Maquir de Lo-debar, cuya casa albergó al lisiado Mefiboset y posteriormente abasteció a David durante la revuelta de Absalón (2 Sam 9:4-5; 17:27). Notablemente, 1 Cr 3:5 identifica a Amiel como padre de Betsabé, mientras que 2 Sam 11:3 lo llama Eliam, con los mismos elementos teofóricos invertidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124948, 'spa', 'Amiud (nombre propio)', 'El nombre propio Amiud, que significa ''mi pariente es majestad'', identifica al menos a cuatro o cinco hombres distintos: el efrateo padre de Elisama, que aparece con mayor frecuencia en los censos y ofrendas de Números (Nm 1:10; 2:18; 7:48, 53; 10:22; 1 Cr 7:26), un líder tribal simeonita (Nm 34:20), un líder neftalita (Nm 34:28), un judío postexílico (1 Cr 9:4) y posiblemente el padre de Talmai, rey de Gesur.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124950, 'spa', 'Hijo de Benaía', 'Hijo de Benaía mencionado en 1 Crónicas 27:6, dentro de la organización militar de David. El significado del nombre, ''mi pariente ha otorgado'', refleja gratitud por las relaciones familiares y la provisión divina. Los testimonios textuales griegos muestran transliteraciones variadas, lo que sugiere que el nombre resultaba poco familiar a los escribas posteriores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124952, 'spa', 'Aminadab', 'Nombre propio que significa ''mi pariente es noble'' o ''mi pueblo es generoso'', referido principalmente al padre de Naasón y suegro de Aarón (Éx 6:23), quien aparece en la línea genealógica de Judá a David (Rt 4:19–20; 1 Cr 2:10). Es cabeza ancestral del contingente tribal de Judá durante el desierto (Nm 1:7; 2:3; 7:12, 17; 10:14). El nombre también pertenece a un levita de David y a un hombre postexílico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124954, 'spa', 'Lo profundo oculto', 'En Daniel 2:22, designa los asuntos profundos y ocultos que solo Dios conoce y puede revelar. El contexto arameo enfatiza la capacidad única de Dios para descubrir lo que yace en la oscuridad y en las profundidades escondidas, contenido que trasciende la observación superficial y la indagación humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124955, 'spa', 'Gavilla de grano', 'Grano segado tendido en hileras o manojos en el campo. Jeremías 9:22 describe la muerte como un segador que deja cuerpos caídos como grano; Amós 2:13 retrata el aplastamiento como un carro sobrecargado de gavillas; Miqueas 4:12 muestra a las naciones enemigas como gavillas reunidas involuntariamente para la trilla (juicio); Zacarías 12:6 usa la inflamabilidad de las gavillas secas como imagen de Judá consumiendo a los pueblos circundantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124956, 'spa', 'Nombre propio danita', 'Nombre personal del líder danita, padre de Ahiezer, que aparece únicamente en Números durante el censo del desierto y las narrativas de ofrendas tribales. El nombre teofórico declara parentesco divino: ''mi pueblo es Shaddai''. Tanto el español ''Amisadai'' como el inglés ''Ammishaddai'' transliteran fielmente el compuesto, atestiguando su transmisión estable entre versiones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124957, 'spa', 'Prójimo (legal-ético)', 'Sentido legal-ético de ''prójimo'' o ''conciudadano'', usado en la legislación levítica para definir a quien se deben obligaciones morales: no robarás a tu prójimo (Lv 19:11), no oprimirás a tu prójimo (Lv 25:17), juzgarás a tu prójimo con justicia (Lv 19:15). Las traducciones destacan la cualidad posesiva y relacional: siempre es tu prójimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124962, 'spa', 'Compañero (relación personal)', 'Sentido personal-relacional que significa ''compañero'' o ''asociado cercano'', en Zacarías 13:7 donde Dios llama al pastor ''el varón que es mi compañero'' (גְּבֶר עֲמִיתִי). Transmite intimidad que trasciende las obligaciones jurídicas de Levítico. El sufijo posesivo de primera persona intensifica la relación: no un simple prójimo, sino un allegado íntimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124963, 'spa', 'Trabajar, afanarse (Qal)', 'Trabajar con fatiga, afanarse extenuantemente — connotación de esfuerzo agotador más que de productividad gozosa. Domina en Eclesiastés como palabra temática: ''¿Qué provecho tiene el hombre de todo su trabajo bajo el sol?'' (Ecl 1:3; cf. 2:11, 19-21; 5:18; 8:17). El Salmo 127:1 lo emplea para el esfuerzo fútil de edificar sin ayuda divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124970, 'spa', 'Penalidad, angustia o aflicción experimentada como sufrimiento — la dimensión do', 'Penalidad, angustia o aflicción experimentada como sufrimiento — la dimensión dolorosa y gravosa de la existencia. Dios hizo que José olvidara ''toda su aflicción'' (Gn 41:51), Balaam no vio ''trabajo'' en Israel (Nm 23:21), y Job desea que alguien hubiera ocultado ''el sufrimiento de sus ojos'' al nacer (Job 3:10). La palabra aquí nombra un padecimiento que no se elige sino que se soporta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124971, 'spa', 'Esfuerzo productivo agotador o labor — el desgaste del trabajo, especialmente ta', 'Esfuerzo productivo agotador o labor — el desgaste del trabajo, especialmente tal como Eclesiastés reflexiona sobre la fatiga humana bajo el sol. Qohélet plantea su pregunta central: ''¿Qué provecho saca el hombre de todo su trabajo (עָמָל) con que se afana?'' (Ec 1:3), mientras el salmista señala que Dios dio a Israel ''el trabajo de los pueblos'' — el fruto de esfuerzos ajenos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124976, 'spa', 'Maldad o perversidad — actividad dañina infligida deliberadamente a otros median', 'Maldad o perversidad — actividad dañina infligida deliberadamente a otros mediante opresión o injusticia. Isaías denuncia a los que ''decretan iniquidad'' por estatuto (Is 10:1), y el salmista pide que ''la maldad de sus propios labios'' cubra a los malvados (Sal 140:9). Este sentido pasa del padecimiento pasivo al daño activo e intencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124996, 'spa', 'Descendiente de Aser', 'Descendiente de Aser registrado en 1 Crónicas 7:35, dentro de una secuencia genealógica. Aunque la raíz podría sugerir ''esfuerzo'' o ''labor'', aquí el nombre funciona como identificador familiar. Las traducciones generalmente conservan la forma fonética, reconociendo su función como nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124997, 'spa', 'Trabajador o sufriente', 'Quien labora o sufre bajo una carga. Jueces 5:26 lo usa para obreros; Proverbios 16:26 para el trabajador impulsado por el hambre. Job lo emplea para sufrientes: los de alma amargada (3:20) y el afligido que pierde su riqueza (20:22). El término une el trabajo físico y el sufrimiento emocional o corporal, ambos implicando resistencia ante la dificultad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124998, 'spa', 'Afanarse, trabajar penosamente', 'Describe a la persona que se afana con labor agotadora y gravosa, usado predicativamente en Eclesiastés para caracterizar el esfuerzo humano bajo el sol. En Ecl 2:18 y 9:9, el que trabaja confronta la ironía de que el fruto de su esfuerzo pasa a otro. La evidencia multilingüe converge: español ''trabaja'', francés ''labeur'' y alemán ''Mühe'' subrayan esfuerzo extenuante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (124999, 'spa', 'Amalec (nombre propio)', 'Amalec (nombre propio): el nombre propio Amalec, que funciona tanto como nombre personal del antepasado (Gn 36:12, 16) como designacion colectiva gentilicia para la nacion amalecita a lo largo de toda la historia de Israel: Exodo (Ex 17:8-16), peregrinacion por el desierto (Nm 13:29; 24:20), jueces (Jue 3:13; 6:3), monarquia (1 Sam 14-15; 30) y eliminacion del remanente (1 Cr 4:43). Las glosas multilingues transliteran uniformemente como ''Amalec/Amaleq'' en todas las lenguas estudiadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125007, 'spa', 'Amalecita (gentilicio)', 'Gentilicio que designa a un miembro o al conjunto del pueblo amalecita, descendientes del nieto de Esaú, Amalec. Se usa para la nación junto a los cananeos (Nm 14:25, 43, 45), en referencias geográficas (Gn 14:7; Jue 12:15) y para individuos en las campañas de Saúl (1 S 15:6; 30:13; 2 S 1:8, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125015, 'spa', 'Oscurecer y eclipsar', 'Tres apariciones con matices variados: oscurecimiento literal (Lamentaciones), ocultación (Ezequiel 28) y eclipsamiento (Ezequiel 31). El uso en Lamentaciones es el más poderoso: el oro que se opaca se convierte en metáfora de la gloria perdida y de lo precioso degradado. Los usos en Ezequiel son figurados, ampliando el sentido desde lo físico hacia la superioridad y el encubrimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125016, 'spa', 'Nombre profético simbólico', 'El nombre simbólico עִמָּנוּאֵל (Dios-con-nosotros) dado al niño-señal de Isaías. Isaías 7:14 lo presenta como garantía a Acaz de que la coalición amenazante caerá. En 8:8 y 8:10 (apareciendo dos veces como עִמָּנוּ אֵל), el nombre se transforma en declaración de fe en la presencia protectora de Dios. Las cuatro apariciones (incluyendo la forma dividida) subrayan la teología de la inmanencia divina en tiempos de crisis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125017, 'spa', 'Cargar activamente', 'Formas activas del Qal e Hifil que denotan el acto físico de cargar fardos sobre animales o transportar cargas. Génesis 44:13 muestra a los hermanos cargando sus asnos; Nehemías 13:15 describe a mercaderes cargando productos en sábado; el Salmo 68:20 celebra al Dios que «cada día nos carga». Abarca tanto el uso cotidiano como el teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125021, 'spa', 'Ser cargado (pasivo)', 'Formas pasivas del participio Qal que describen el estado de ser cargado o llevado como peso. Isaías 46:1 presenta los ídolos babilónicos «cargados» sobre bestias exhaustas, mientras que Isaías 46:3 invierte la imagen con Israel «llevado» por Dios desde el vientre materno. El contraste pasivo entre objetos acarreados y un pueblo sostenido por Dios es fundamental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125026, 'spa', 'Oficial de Josafat', 'Oficial mencionado en 2 Crónicas 17:16, que se ofreció voluntariamente al servicio de Yahvé. El elemento teofórico vincula al portador con Yahvé, mientras la raíz verbal sugiere ser sostenido o llevado por Dios. Los testimonios griegos lo transcriben de diversas formas, incluyendo la lectura ''Amasias'' que lo asimila al más conocido Amasías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125027, 'spa', 'Ciudad en Aser', 'Asentamiento en el territorio de Aser, registrado en Josué 19:26 como parte de una lista de límites territoriales. El nombre aparece con la conjunción ''y'' dentro de una enumeración de localidades fronterizas. Las traducciones europeas generalmente conservan la forma ''Amad'', adaptando únicamente la conjunción según la gramática de cada lengua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125028, 'spa', 'Profundizar (Hifil causativo)', 'Formas causativas del Hifil con significado de «hacer profundo, profundizar, ahondar», tanto literal como figuradamente. Isaías 7:11 invita a Acaz a pedir una señal tan profunda como el Seol; Isaías 29:15 y 31:6 condenan a quienes se hunden en la rebelión; Isaías 30:33 describe a Tofet hecho «profundo y ancho»; Jeremías 49:8 advierte a Edom que se esconda en lo profundo; Oseas 5:2 y 9:9 retratan la corrupción de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125032, 'spa', 'Ser profundo (Qal estativo)', 'Única aparición del Qal estativo en el Salmo 92:5, que declara que los pensamientos de Dios «son profundos»: un uso contemplativo y adjetival que expresa la cualidad insondable de la sabiduría divina. A diferencia del Hifil activo, esta forma se maravilla de la profundidad como atributo existente de la mente de Dios, contrastado con la insensatez del necio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125035, 'spa', 'Valle amplio o llanura baja de fondo plano situada entre colinas o montañas, gen', 'Valle amplio o llanura baja de fondo plano situada entre colinas o montañas, generalmente apta para la agricultura y a menudo lugar de enfrentamientos militares. Se distingue de גַּיְא (garganta estrecha, H1516) y נַחַל (wadi, H5158) por su amplitud y apertura. Aparece frecuentemente en construcciones toponímicas: Valle de Elá (1 S 17:2), Valle de Jezreel (Jue 6:33), Valle del Rey (Gn 14:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125059, 'spa', 'Profundidad insondable', 'Usado en Proverbios 25:3 para describir la profundidad inescrutable del corazón de los reyes, que como la profundidad física no puede medirse ni sondearse por medios ordinarios. El término crea una metáfora espacial para la inaccesibilidad intelectual o emocional, transmitiendo la idea de que ciertos conocimientos permanecen fuera del alcance humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125060, 'spa', 'Habla incomprensible', 'Habla profunda o incomprensible, lenguaje demasiado oscuro para entender. Isaías 33:19 lo usa para un pueblo extranjero cuyo discurso es ininteligible. Ezequiel 3:5-6 contrasta a los pueblos «de habla profunda» (a quienes el profeta NO es enviado) con Israel, que habla hebreo comprensible. Proverbios 9:18 emplea posiblemente una forma relacionada para las «profundidades» del Seol. La aplicación constante al lenguaje incomprensible sugiere profundidad como impenetrabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125061, 'spa', 'Profundidad física y medible', 'Profundidad física y medible. Usado repetidamente en las regulaciones de pureza de Levítico 13 donde el sacerdote debe determinar si una afección cutánea es ''más profunda que la piel'' (Lv 13:3, 4, 25, 30, 31, 32, 34). También describe una copa profunda (Ez 23:32) y el ''foso profundo'' de la mujer adúltera (Pr 22:14; 23:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125062, 'spa', 'Profundidad abstracta e inescrutable —lo que está más allá del alcance o la comp', 'Profundidad abstracta e inescrutable —lo que está más allá del alcance o la comprensión humana. El propósito de Dios es ''más profundo que el Seol'' (Job 11:8), y Él ''revela cosas profundas de la oscuridad'' (Job 12:22). El corazón maquinador es llamado ''profundo'' en Sal 64:6, y Eclesiastés lamenta dos veces: ''lo que está lejos y sumamente profundo, ¿quién lo hallará?'' (Ec 7:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125069, 'spa', 'Atador de gavillas', 'El que ata gavillas en el Salmo 129:7, dentro de una fórmula de maldición contra los enemigos de Israel. La imagen proviene del trabajo de la cosecha: tras segar el grano, el atador lo reúne en haces manejables. El español preserva el contenido semántico completo con «el que ata gavillas», mientras que el inglés abrevia a ''gatherer'', centrándose solo en el aspecto de recolección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125071, 'spa', 'Lana pura', 'Usado en Daniel 7:9 para describir el cabello del Anciano de Días como lana pura, enfatizando una blancura resplandeciente. El símil «como lana» evoca una imagen visual de pureza y venerable ancianidad. Las lenguas romances conservan la estructura comparativa («como lana», «comme laine»), mientras que otras versiones muestran variaciones en la comprensión de este raro término arameo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125072, 'spa', 'Gavilla de grano', 'Gavilla o manojo atado de tallos de grano cortados, unidad básica del campo de cosecha. Central en la ofrenda mecida de primicias (Lev 23:10-15), donde el sacerdote eleva la primera gavilla ante el SEÑOR, y en la ley del espigueo (Deut 24:19), que ordena dejar gavillas olvidadas para los vulnerables. Rut 2:7, 15 ilustra esta práctica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125077, 'spa', 'El omer', 'Medida de capacidad para áridos equivalente a la décima parte de un efa (aproximadamente 2,3 litros), empleada exclusivamente en el relato del maná de Éxodo 16. Funciona como la cantidad diaria prescrita por cabeza (Exod 16:16, 18, 22) y como la porción conservada en vasija memorial ante el arca (Exod 16:32–33). Las traducciones modernas transliteran uniformemente el término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125080, 'spa', 'El nombre propio Amorah (Gomorra), que designa la ciudad de la llanura del Jordá', 'El nombre propio Amorah (Gomorra), que designa la ciudad de la llanura del Jordán destruida junto con Sodoma por fuego divino (Gn 19:24-28). Siempre aparece emparejada con Sodoma, funcionando como emblema proverbial de ruina total bajo el juicio de Dios. Usada históricamente en las narrativas de Génesis (Gn 10:19; 13:10; 14:2, 8) y proféticamente como fórmula de advertencia: ''como la destrucción de Sodoma y Gomorra'' (Is 13:19; Jer 49:18; Am 4:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125086, 'spa', 'El nombre propio Omri, aplicado a cuatro individuos distintos', 'El nombre propio Omri, aplicado a cuatro individuos distintos. El más prominente es el rey Omri de Israel, comandante del ejército aclamado rey por las tropas en Guibetón, quien reinó desde Tirsa y luego construyó Samaria (1 Re 16:16-28). La escritura cuneiforme asiria (Humri) y la Estela de Mesa atestiguan su importancia internacional. Tres figuras menores en Crónicas también llevan el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125088, 'spa', 'Amram', 'Nombre propio del padre de Moisés, Aarón y Miriam, hijo de Coat y nieto de Leví. Central en las genealogías levíticas tanto de Éxodo como de Crónicas (Éx 6:18, 20; Nm 3:19; 26:58-59; 1 Cr 5:28-29; 6:3; 23:12-13; 24:20). Sus descendientes, los amramitas, forman una subdivisión levítica reconocida con deberes asignados en el tabernáculo y el templo (Nm 3:27; 1 Cr 26:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125091, 'spa', 'Nombre propio masculino que identifica principalmente al hijo de Jeter (o Itra) ', 'Nombre propio masculino que identifica principalmente al hijo de Jeter (o Itra) y Abigail, hermana de David, quien sirvió como general de Absalón y fue luego asesinado por Joab (2 Sam 17:25; 19:13; 20:4-12; 1 Re 2:5, 32; 1 Cr 2:17). Un segundo portador del nombre es un líder efrateo que instó a la compasión hacia los prisioneros de guerra (2 Cr 28:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125095, 'spa', 'Nombre personal', 'Nombre propio de varios israelitas que desempeñaron funciones de guerrero, levita y sacerdote. El portador más memorable es el guerrero davídico de 1 Cr 12:19, cuyo juramento de lealtad empoderado por el Espíritu emplea lenguaje pactual. Tanto el español como el inglés transliteran uniformemente «Amasai», mientras que el francés y el alemán conservan la forma hebrea entre corchetes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125096, 'spa', 'Nombre sacerdotal', 'Un sacerdote mencionado en Nehemías 11:13 entre los que habitaban en Jerusalén. El pasaje paralelo de 1 Crónicas 9:12 presenta «Maasai», lo que lleva a los eruditos a sospechar corrupción textual. Los testimonios de la Septuaginta reflejan incertidumbre sobre la forma del nombre. Como nombre propio, las traducciones lo transliteran o lo dejan en caracteres hebreos, reconociendo la dificultad textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125098, 'spa', 'El fruto de la uva, usado tanto colectivamente para las uvas como producto agríc', 'El fruto de la uva, usado tanto colectivamente para las uvas como producto agrícola como individualmente para la baya de uva. Aparece en contextos de viticultura y cosecha: el copero del faraón exprimiendo uvas (Gn 40:10-11), el enorme racimo de los espías traído de Canaán (Nm 13:23), las regulaciones de abstinencia del nazareo (Nm 6:3) y las provisiones del año sabático (Lv 25:5). También lleva fuerza figurada en la parábola de la viña (Is 5:2, 4) y las ''uvas de veneno'' (Dt 32:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125106, 'spa', 'Deleitarse, gozar', 'Sentido reflexivo principal en el Hitpael: deleitarse profundamente en algo, experimentar un placer absorto y exquisito. La mayoría de las apariciones giran en torno al deleite en Dios o sus caminos: «Deléitate en el SEÑOR» (Sal 37:4), «los humildes se deleitarán en abundante paz» (Sal 37:11), «te deleitarás en el Todopoderoso» (Job 22:26). Isaías 55:2 e Isaías 58:14 extienden el objeto de Dios a sus provisiones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125110, 'spa', 'Delicadeza, lujo regalado', 'El infinitivo constructo del Hitpael usado como sustantivo abstracto en Deuteronomio 28:56, designando la condición de delicadeza o lujo mimado. La «mujer tierna y delicada» se caracteriza por su refinamiento habitual e indulgencia. Aquí la palabra no habla de gozo espiritual, sino de una vida tan protegida que caminar sobre suelo descubierto resulta impensable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125111, 'spa', 'Burlarse, mofarse', 'Un giro brusco del Hitpael en Isaías 57:4, donde el verbo adquiere un tono de mofa y escarnio: «¿De quién os burláis? ¿Contra quién abrís la boca?» El deleite aquí es malicioso: gozar al provocar al otro. Solo una ocurrencia lleva este sentido, pero demuestra cómo el placer reflexivo puede volverse hostil y despectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125113, 'spa', 'Persona delicada, mimada', 'El participio Pual en Jeremías 6:2, que describe a Jerusalén como una mujer «delicada» o «mimada», alguien ablandada por la indulgencia ajena. A diferencia del Hitpael, donde el sujeto se deleita a sí mismo, el Pual pasivo marca un mimo externo: la ciudad ha sido tratada con ternura y por ello es vulnerable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125117, 'spa', 'Delicadeza y refinamiento', 'Tres apariciones: dos en las maldiciones de asedio de Deuteronomio (formas masculina y femenina) y una en el oráculo contra Babilonia en Isaías. Los retratos paralelos de Deuteronomio 28 —el hombre delicado y la mujer delicada— ambos descienden al canibalismo, mostrando cómo la guerra de asedio arranca toda civilización. El uso en Isaías invierte el lujo en humillación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125119, 'spa', 'Habitar o aullar', 'Usado en Isaías 13:22 para describir la acción de los chacales en las ruinas de Babilonia. El hebreo permite las lecturas «habitarán» o «aullarán», y las versiones antiguas están divididas. El español «aullarán» y el alemán «antwortete» (respondió) reflejan la comprensión tradicional de los gritos animales, mientras que el paralelo estructural con «habitar» en el versículo 21 sugiere habitación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125120, 'spa', 'responder, contestar', 'Responder, contestar o replicar verbalmente a una pregunta, declaración o situación implícita: el sentido primario abrumadoramente dominante con 289 ocurrencias. Abarca la fórmula narrativa וַיַּעַן (''y respondió''), respuestas directas en diálogos y la respuesta de Dios a la oración. Las traducciones multilingües convergen en vocabulario estándar de respuesta: respondió, répondit, antwortete, 대답했다.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125136, 'spa', 'testificar, dar testimonio', 'Testificar, dar testimonio o declarar formalmente: 18 ocurrencias concentradas en contextos legales y de alianza. El noveno mandamiento (Éx 20:16; Dt 5:20) prohíbe ''responder'' contra el prójimo como testigo falso, pero el sentido es claramente ''testificar'' y no simplemente ''responder''. Nm 35:30 especifica que nadie ''testificará'' contra otro con un solo testigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125138, 'spa', 'cantar responsorialmente', 'Cantar responsorialmente o responder con canto: sentido antifonal o coral que aparece en 3 pasajes. En Os 2:15 Israel ''cantará/responderá'' como en los días de su juventud; Dt 31:21 habla del Cántico de Moisés ''respondiendo'' ante Israel; y Dt 25:9 emplea el verbo para la respuesta formal en la ceremonia del levirato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125187, 'spa', 'ser respondido (Nifal)', 'Ser respondido o recibir respuesta: forma Nifal (pasiva) con 3 ocurrencias. Job 11:2 pregunta si ''la multitud de palabras será respondida''; Job 19:7 lamenta ''clamo pero no soy respondido''; Pr 21:13 advierte que quien ignora al pobre ''clamará y no será respondido''. Todas las traducciones emplean formas pasivas equivalentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125189, 'spa', 'ser humillado, silenciado', 'Ser abatido o silenciado: una única ocurrencia en Is 25:5, donde ''el estruendo de los extranjeros es acallado''. Parece tratarse de una superposición homonímica con otra raíz עָנָה (II), que significa ''ser humillado o afligido'', pero el algoritmo de agrupación lo ubicó aquí por la forma superficial compartida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125228, 'spa', 'gritar, dar voces', 'Gritar o alzar un clamor, donde el énfasis recae en la intensidad vocal más que en la melodía. En Éxodo 32:18, Moisés distingue entre gritos de victoria, lamentos de derrota y el sonido de ''canto'' — usando esta raíz para el ruido vocal mismo. Jeremías 51:14 describe a guerreros alzando un grito sobre Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125230, 'spa', 'cantar, entonar (Qal)', 'Cantar o entonar en la conjugación Qal, abarcando el canto general ya sea como mandato, descripción o acción habitual. Israel canta junto al pozo (Nm 21:17), las mujeres cantan sobre las proezas de David (1 S 21:12; 29:5), y el salmista promete que su lengua ''cantará'' la palabra de Dios (Sal 119:172). El Salmo 147:7 lo usa para la respuesta musical al Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125231, 'spa', 'responder antifonalmente', 'Responder antifonalmente o contestar con canto, especialmente en contextos litúrgicos o de adoración comunitaria. Miriam ''respondió'' al canto de los hombres junto al mar (Éx 15:21), las mujeres ''se respondían'' unas a otras cantando sobre Saúl y David (1 S 18:7), y los levitas ''respondieron'' con alabanza en la dedicación del templo de Esdras (Esd 3:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125232, 'spa', 'cantar, entonar (Piel)', 'Cantar en la conjugación intensiva Piel, sugiriendo alabanza deliberada, sostenida o litúrgica. Isaías 27:2 presenta una ''viña deleitosa — ¡cantadle!'' usando el imperativo Piel para el canto comunitario enfático. La forma intensiva eleva el canto ordinario a adoración intencional, y Éxodo 32:18 lo empareja con el sonido que Moisés oye al descender del monte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125241, 'spa', 'Ocupación divinamente asignada', 'Tres apariciones en Eclesiastés que exploran el tema de la ocupación divinamente dispuesta. Eclesiastés 1:13 introduce «la penosa tarea que Dios ha dado», mientras 3:10 habla de «la labor que Dios ha encomendado a los hombres». En 5:19, el matiz se torna positivo: Dios mantiene a la persona ocupada con gozo. La evidencia multilingüe muestra tratamientos diversos, algunos reconociendo la raíz de aflicción y otros la de ocupación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125242, 'spa', 'El sentido Piel activo dominante', 'El sentido Piel activo dominante: causar sufrimiento, angustia u opresión a alguien. Usado paradigmáticamente de los capataces egipcios que afligían a Israel (Éx 1:11-12), del maltrato humano (Gn 31:50 ''si afliges a mis hijas'') y de la acción disciplinaria de Dios. Consistentemente traducido como afligir u oprimir en las lenguas modernas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125246, 'spa', 'Humillar o rebajar en estatus u orgullo, enfatizando la reducción de la autoexal', 'Humillar o rebajar en estatus u orgullo, enfatizando la reducción de la autoexaltación más que el dolor físico. Deuteronomio 8:2-3 es el texto paradigmático: ''te humilló y te dejó tener hambre y te alimentó con maná, para que supieras que no solo de pan vive el hombre''. Muestra la dimensión pedagógica o moral que distingue este sentido de la mera aflicción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125247, 'spa', 'Qal intransitivo', 'Qal intransitivo: estar en un estado de aflicción o sufrimiento, sin especificar agente externo. Salmo 119:67 ''antes de ser afligido me descarrié'' y 116:10 ''fui muy afligido'' ejemplifican este uso pasivo-estativo. Marca el sufrimiento experimentado más que la imposición activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125252, 'spa', 'Hitpael reflexivo', 'Hitpael reflexivo: afligirse a sí mismo o humillarse, habitualmente asociado al ayuno y las prácticas penitenciales. Levítico 16:29, 31 lo usa para el Día de la Expiación: ''afligiréis vuestras almas'', entendido universalmente como ayuno. Esdras 8:21 y Daniel 10:12 vinculan igualmente la autohumillación con la búsqueda de Dios mediante la abstinencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125253, 'spa', 'Nifal reflexivo-pasivo', 'Nifal reflexivo-pasivo: ser humillado o someterse, a menudo aceptando o soportando voluntariamente la aflicción con mansedumbre. Isaías 53:7 es el arquetipo: ''fue oprimido y afligido, pero no abrió su boca''. La sumisión semejante a un cordero bajo la aflicción distingue este sentido de la simple victimización pasiva — hay una postura de aceptación evidente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125266, 'spa', 'Pual pasivo del Piel', 'Pual pasivo del Piel: ser sometido a aflicción u opresión por un agente externo como receptor del sufrimiento activo. Isaías 53:4 ''herido, golpeado por Dios y afligido'' emplea múltiples formas pasivas. Salmo 132:1 ''recuerda todas sus aflicciones''. El rol de paciente/receptor está codificado gramaticalmente, distinguiéndolo del estado intransitivo Qal y de la postura reflexiva Nifal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125270, 'spa', 'Hifil causativo de aflicción', 'Hifil causativo de aflicción: hacer que alguien entre en un estado de opresión o sufrimiento. Variante de tronco poco frecuente (solo 2 veces) que se solapa con el Piel causativo más común pero puede conllevar un matiz de agencia o inmediatez. 1 Reyes 8:35, 2 Crónicas 6:26 en la oración de dedicación del templo de Salomón: ''cuando tú los aflijas'' en el contexto del juicio divino que retiene la lluvia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125277, 'spa', 'Violencia sexual', 'Violencia sexual: el Piel usado específicamente para la violación o el abuso forzado de una mujer. Génesis 34:2 (Siquem ''la humilló''), 2 Samuel 13:14 (Amnón ''la violó''), Deuteronomio 22:24, 29 en textos legales, Ezequiel 22:10-11 en denuncia profética. Este sentido está claramente lexicalizado en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125286, 'spa', 'Probablemente la raíz homónima עָנָה I ''responder, contestar'' y no עָנָה II ''afl', 'Probablemente la raíz homónima עָנָה I ''responder, contestar'' y no עָנָה II ''afligir'', pero incluida tal como aparece en los datos fuente. Joel 2:19 ''Yahvé respondió y dijo'', 2 Samuel 22:36 ''tu condescendencia me engrandeció'' (posiblemente ''tu respuesta''). La distancia semántica es enorme — comunicación frente a sufrimiento — lo que sugiere que estas tres ocurrencias pertenecen a un lexema distinto que comparte la forma consonántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125293, 'spa', 'Sobreescrito del Salmo 88', 'Sobreescrito del Salmo 88:1 ''Majalat Leanot'' — posiblemente ''para aflicción'' o ''para ser cantado antifonalmente'' (si proviene de עָנָה I). Demasiado aislado y contextualmente incierto (aparece en una notación musical técnica) para asignar un significado con confianza. Podría ser un nombre propio, un término musical o una indicación litúrgica más que el verbo en sí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125314, 'spa', 'El verbo arameo ''responder, contestar,'' siempre unido a אֲמַר (''dijo'') en la fra', 'El verbo arameo ''responder, contestar,'' siempre unido a אֲמַר (''dijo'') en la frase formulaica ''respondió y dijo.'' Abarca tanto la respuesta directa a una pregunta (Dan 2:5; 3:16; 5:17; 6:13) como el habla reactiva provocada por una situación sin pregunta previa (Dan 2:15, 20, 47; 3:9, 14, 28; 4:27). Esta combinación enmarca cada diálogo importante en las narrativas cortesanas e interpretaciones de visiones de Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125318, 'spa', 'Los pobres', 'En Daniel 4:27, se refiere a los pobres o necesitados hacia quienes se aconseja a Nabucodonosor mostrar misericordia como parte de su arrepentimiento. El término arameo enfatiza a quienes padecen angustia económica o vulnerabilidad social. La expresión constructa intensifica el sentido de carencia y dependencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125319, 'spa', 'Aná', 'Nombre propio edomita-horita. El portador principal es el hijo de Zibeón que descubrió fuentes termales mientras pastoreaba asnos (Gn 36:24) y padre de Oholibama, esposa de Esaú (Gn 36:2, 14, 18, 25). Un segundo Aná aparece como hijo de Seir el horita (Gn 36:20, 29; 1 Cr 1:38, 40).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125321, 'spa', 'Humilde, manso o apacible en disposición, describiendo a quienes son de espíritu', 'Humilde, manso o apacible en disposición, describiendo a quienes son de espíritu bajo ante Dios y los demás, confiando en la vindicación divina en vez de la autoafirmación. Moisés es el paradigma del ''anav'' (Nm 12:3), y los Salmos prometen repetidamente que Dios levanta y satisface a los mansos (Sal 22:26; 25:9; 37:11; 147:6; 149:4). El Sal 37:11 es la fuente directa de la bienaventuranza de Jesús: ''los mansos heredarán la tierra''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125324, 'spa', 'Pobre, afligido o de baja condición socioeconómica, enfatizando la privación mat', 'Pobre, afligido o de baja condición socioeconómica, enfatizando la privación material o la opresión externa más que el carácter interior. En Job 24:4 los ''anavim'' son empujados fuera del camino por los malvados; en Isaías 32:7 el perverso trama planes para arruinarlos; en Proverbios 14:21 la bendición viene a quien es bondadoso con ellos. La superposición con el sentido 1 refleja la visión hebrea de que la humildad interior y la pobreza exterior a menudo van unidas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125338, 'spa', 'Nombre propio', 'Descendiente de Judá mencionado en 1 Crónicas 4:8. Los testimonios de la Septuaginta difieren notablemente en sus intentos de transliteración (Ennon, Anob), lo que sugiere que el nombre resultaba desconocido para los escribas griegos posteriores. Las traducciones modernas generalmente mantienen la forma fonética del nombre hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125340, 'spa', 'Humildad ante Dios', 'La virtud de la humildad o mansedumbre, especialmente delante de Dios. Tres apariciones en Proverbios (15:33, 18:12, 22:4) vinculan la humildad con el honor, el temor de Dios y la bendición. Sofonías 2:3 exhorta a los humildes a ''buscar la humildad,'' convirtiéndola en una búsqueda activa. El término encarna el ideal bíblico de modestia apropiada que reconoce la supremacía de Dios y conduce a la exaltación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125341, 'spa', 'Aflicción del sufriente', 'En el Salmo 22:24, se refiere a la aflicción del sufriente a quien Dios no desprecia, aunque también podría aludir a la humildad como rasgo de carácter. La relación constructa «aflicción del afligido» crea una expresión intensiva. El término conecta la condición de abajamiento, ya sea voluntario o impuesto, con la atención compasiva de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125342, 'spa', 'Aflicción, miseria, angustia o sufrimiento causado por la pobreza, la opresión o', 'Aflicción, miseria, angustia o sufrimiento causado por la pobreza, la opresión o la adversidad. Es la condición que provoca la compasión e intervención divina: Dios ve la aflicción de Agar (Gn 16:11), oye el clamor de Israel desde Egipto (Éx 3:7) y recuerda las penalidades de Jacob (Gn 31:42). José nombra a su hijo Efraín porque ''Dios me hizo fructificar en la tierra de mi aflicción'' (Gn 41:52).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125356, 'spa', 'Humildad o mansedumbre de carácter, describiendo una disposición modesta y apaci', 'Humildad o mansedumbre de carácter, describiendo una disposición modesta y apacible más que una adversidad externa. Números 12:3 aplica de manera única esta cualidad a Moisés: ''el varón Moisés era muy manso, más que todos los hombres sobre la faz de la tierra.'' Esta única atestación tiende un puente entre el sentido concreto de sufrimiento y la virtud interior de la humildad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125361, 'spa', 'La persona materialmente pobre o indigente, constituyendo una clase social recon', 'La persona materialmente pobre o indigente, constituyendo una clase social reconocida en la legislación israelita. La Torá ordena dejar las esquinas de la cosecha y las espigas caídas para el עָנִי (Lv 19:10; 23:22), garantizando el pago del jornal en el mismo día (Dt 24:15) — protecciones que reflejan una vulnerabilidad económica genuina, no mera desgracia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125363, 'spa', 'Quien sufre aflicción, opresión o profunda angustia, donde el énfasis recae en l', 'Quien sufre aflicción, opresión o profunda angustia, donde el énfasis recae en la experiencia del dolor más que en la carencia material. David alaba a Dios por no esconder su rostro del afligido (Sal 22:24), y Elihú declara que Dios libra al עָנִי a través de su sufrimiento (Job 36:15) — la condición presupone un clamor que asciende al cielo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125371, 'spa', 'Vocativo femenino que se dirige a una ciudad personificada — típicamente Jerusal', 'Vocativo femenino que se dirige a una ciudad personificada — típicamente Jerusalén o Sion — como una figura sufriente y azotada por la tormenta. Isaías 54:11 exclama ''¡Oh afligida, azotada por la tempestad y sin consuelo!'', usando la forma femenina como un epíteto tierno para una comunidad que soporta el juicio colectivo pero que aguarda la restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125380, 'spa', 'Humilde o manso de espíritu ante Dios, denotando una disposición interior más qu', 'Humilde o manso de espíritu ante Dios, denotando una disposición interior más que una condición externa. Este es el sentido de Zacarías 9:9, donde el Rey mesiánico viene עָנִי — manso, montado sobre un asno. Proverbios 3:34 lo empareja con el favor divino: Dios da gracia a los humildes. El hebreo cambia deliberadamente de la circunstancia al carácter.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125396, 'spa', 'Nombre de levitas músicos', 'Nombre propio de músicos levíticos y servidores del templo. 1 Crónicas 15:18, 20 incluye a Uni entre los designados para el ministerio musical. Nehemías 12:9 menciona a Uno (con variante Ketiv/Qere) entre los levitas postexílicos. Las variantes textuales y la diversidad en la LXX indican cierta fluidez en la transmisión del nombre, pero identifican claramente a personal de adoración levítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125398, 'spa', 'Ciudad de Judá', 'Asentamiento en la región montañosa de Judá mencionado en Josué 15:50. El nombre aparece con la conjunción copulativa en la lista hebrea de límites territoriales. La identificación moderna lo sitúa en la zona al oeste-suroeste de Hebrón. Las traducciones mantienen la forma fonética «Anim» como nombre geográfico propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125399, 'spa', 'Tarea, ocupación, quehacer', 'Tarea, ocupación o quehacer gravoso que absorbe y preocupa, particularmente como afán divinamente asignado. Aparece predominantemente en Eclesiastés, donde Qohélet la emplea para caracterizar el frustrante ciclo de la actividad humana: ''la tarea que Dios ha dado a los hijos de los hombres'' (Ecl 1:13, 3:10). Abarca el esfuerzo incesante y la labor sin reposo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125404, 'spa', 'Ciudad levítica', 'Ciudad registrada en 1 Crónicas 6:73 como posesión levítica, que representa una forma corrompida de En-ganim según Josué 19:21 y 21:29. El problema textual involucra la pérdida de sílabas iniciales, produciendo esta forma abreviada. La mayoría de las traducciones conservan la forma hebrea o reconocen la dificultad textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125408, 'spa', 'Practicar adivinación', 'Dedicarse a la adivinación, el agorerismo o la lectura de presagios, práctica estrictamente prohibida en la legislación del Torá (Lv 19:26; Dt 18:10, 14). El participio meʿonen designa al practicante como agorero profesional, enumerado junto a hechiceros, encantadores y nigromantes en el catálogo deuteronómico de abominaciones cananeas. La adopción de esta práctica por Manasés representa la apostasía real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125418, 'spa', 'Masa nubosa en el cielo, usada predominantemente para la nube teofánica que mani', 'Masa nubosa en el cielo, usada predominantemente para la nube teofánica que manifiesta la presencia de Dios — la columna de nube (Éx 13:21-22), la nube espesa del Sinaí (Éx 19:9, 16) y la nube de gloria que llenaba el tabernáculo y el templo (1 R 8:10-11). También se emplea para nubes meteorológicas comunes y figuradamente para lo efímero (Os 6:4) o lo que encubre (Job 26:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125439, 'spa', 'Ramas del árbol visionario', 'Ramas del árbol en la visión de Daniel sobre el árbol cósmico. Las cuatro apariciones (Dan 4:12, 14, 14, 21) describen las ramas del árbol soñado por Nabucodonosor: inicialmente dando refugio a las aves (''en sus ramas''), luego cortadas en juicio. Las ramas simbolizan el alcance del poder imperial y, al ser removidas, la pérdida del dominio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125440, 'spa', 'Rama, ramaje', 'Rama o ramaje de un árbol o vid, empleado en sentido concreto y figurado. Levítico 23:40 prescribe recoger ramas frondosas para Sucot. Ezequiel lo utiliza en sus alegorías de la vid y el cedro: la vid que echa ramas (Ez 17:8), el cedro que cobija naciones (Ez 17:23; 31:3), y la promesa de fecundidad renovada para Israel (Ez 36:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125446, 'spa', 'Adornar y proveer', 'Tres apariciones, aunque dos corresponden a la construcción enfática de infinitivo en Deuteronomio 15:14 (proveer abundantemente). Salmo 73:6 usa el Qal para decir que la soberbia «adorna» a los impíos como joyería visible. El uso en Deuteronomio es figurado: tratar generosamente al siervo liberado se convierte en «hacerle un collar» con provisiones. La evidencia multilingüe refleja incertidumbre traductológica entre el sentido literal de adorno y el figurado de provisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125447, 'spa', 'Collar o pendiente', 'Tres apariciones mostrando collares en contextos variados: botín militar, adorno de la sabiduría e imágenes eróticas. La evidencia multilingüe consistentemente traduce ''collar/cadenas'', mostrando la idea central de joyería para el cuello. Jueces 8:26 lo agrupa con lunas crecientes y vestiduras de púrpura como precioso botín. Proverbios 1:9 lo empareja con la imagen de guirnalda/corona, ambos representando el efecto embellecedor de la sabiduría. Cantares 4:9 usa la imagen de manera íntima y personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125448, 'spa', 'El Anac', 'Anac, el legendario ancestro de los gigantes anaceos, cuyo nombre se relaciona con la palabra hebrea para «cuello», posiblemente indicando gran estatura. Se le menciona en el relato de los espías (Nm 13:22, 28, 33), en la retrospectiva deuteronómica de la conquista (Dt 9:2) y en la asignación del territorio a Caleb (Jos 15:13-14). El uso frecuente del artículo definido («el Anac») en hebreo sugiere un título de clan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125450, 'spa', 'Anaceos (pueblo gigante)', 'Los anaceos, pueblo de legendaria estatura descendiente de Anac, que habitaba principalmente la zona de Hebrón y el territorio filisteo. Deuteronomio los usa como prueba de fe: aunque eran grandes y altos (Dt 1:28; 9:2), Dios ya había desposesionado a otros pueblos gigantes a favor de otras naciones (Dt 2:10-11, 21). Josué registra su derrota final y su casi total expulsión de las colinas de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125455, 'spa', 'Persona y ciudad', 'Tres apariciones: dos en Génesis 14 refiriéndose al aliado de Abraham, una en Crónicas refiriéndose a la ciudad levítica. La evidencia multilingüe muestra prácticas estándar de transliteración, con algunas versiones proporcionando formas genitivas (''de Aner''). El relato de Génesis presenta a Aner como parte de la coalición de Abraham, compartiendo el botín de la victoria y atestiguando su diezmo a Melquisedec. El registro de Crónicas refleja el sistema de ciudades levíticas establecido durante la conquista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125456, 'spa', 'Ser multado o castigado', 'Nifal pasivo: ser multado o castigado, sufrir una pena impuesta por otros. Éxodo 21:22 emplea el infinitivo absoluto enfático (עָנוֹשׁ יֵעָנֵשׁ, «ciertamente será multado») para el caso de herir a una mujer encinta. En Proverbios 22:3 y 27:12, los ingenuos pasan de largo y «son castigados». Abarca desde la multa concreta hasta el castigo general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125457, 'spa', 'Multar, imponer pena', 'Qal activo: multar o imponer una sanción económica específica. Deuteronomio 22:19 prescribe multar al marido calumniador con cien siclos de plata; el faraón Necó multa al país en 2 Crónicas 36:3. Amós 2:8 condena a quienes beben vino comprado «con el dinero de las multas». Este sentido retiene con precisión el carácter monetario de la penalización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125459, 'spa', 'Castigar', 'Qal activo en sentido punitivo más amplio: castigar, sin limitarse a la multa económica. Proverbios 17:26 afirma que no es bueno castigar al justo, y 21:11 enseña que cuando se castiga al burlador, el simple adquiere sabiduría. El paso de «multar» a «castigar» señala la transición de la sanción financiera a la disciplina general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125467, 'spa', 'Anatot (ciudad levítica)', 'La ciudad levítica de Anatot en el territorio de Benjamín, identificada de modo uniforme en sus quince apariciones como una misma localidad cerca de Jerusalén. Sirve como lugar de destierro de Abiatar (1 Re 2:26), patria de Jeremías y escenario de su compra profética de un campo (Jer 1:1; 32:7–9), y figura en los censos postexílicos (Esd 2:23; Neh 7:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125471, 'spa', 'Gentilicio de Anatot', 'Adjetivo gentilicio que significa «el de Anatot», aplicado a guerreros en las filas de David (Abiezer, Jehú) y empleado como etiqueta geográfica para identificar el lugar de origen de Jeremías en Jer 29:27. El uso constante del artículo en diversas lenguas — «el anatotita», «the Anathothite», «der Anathothite» — subraya su función como epíteto fijo más que como descriptor casual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125473, 'spa', 'Mosto, jugo dulce', 'Jugo dulce y recién prensado de uvas o frutas, que representa abundancia y vitalidad sin procesar. Aparece en visiones escatológicas de fertilidad desbordante (Jl 3:18; Am 9:13) y en Cnt 8:2 como zumo de granada en un contexto íntimo. El español «mosto» y el francés «jus» destacan la cualidad de recién exprimido, mientras que el alemán «Süsswein» enfatiza la dulzura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125475, 'spa', 'Ramas, follaje', 'En el Salmo 104:12, se refiere a las ramas donde las aves habitan y cantan, como parte de la descripción de la provisión de Dios para sus criaturas. Este préstamo arameo indica el follaje arbóreo donde la fauna encuentra refugio. El español «ramas» capta con precisión la referencia botánica, enfatizando la estructura física que provee hábitat.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125476, 'spa', 'Follaje del árbol', 'Tres apariciones, todas describiendo el follaje del árbol del sueño en Daniel 4. La evidencia multilingüe muestra las formas hebreas preservadas entre corchetes, con algunas versiones intentando glosas. El contexto arameo describe el ''hermoso follaje'' del árbol como parte de su magnificencia paradisíaca antes de que venga el decreto de cortarlo. El follaje con sufijo de tercera persona (''sus hojas'') aparece tanto en la narración del sueño como en su interpretación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125477, 'spa', 'Hinchado, arrogante', 'En Habacuc 2:4, describe al alma orgullosa que está «hinchada», en contraste con el justo que vive por la fe. La conjugación Pual sugiere un estado de estar inflado o agrandado, describiendo metafóricamente la soberbia. El versículo llegó a ser fundamental para la doctrina paulina de la justificación por la fe, aunque el enfoque hebreo original recae sobre la arrogancia del impío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125478, 'spa', 'Actuar presuntuosamente', 'En Números 14:44 describe el intento presuntuoso de Israel de subir a la región montañosa después de que Dios lo prohibiera, tras su rebelión anterior. La conjugación Hifil puede indicar hacerse a sí mismo negligente o actuar con atrevimiento. La tradición lexicográfica sugiere tanto presunción como imprudencia, reflejando la naturaleza obstinada y no autorizada de la acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125479, 'spa', 'Montículo fortificado', 'Tres apariciones refiriéndose a montículos fortificados: Samaria (2 Reyes), Jerusalén (Isaías) y Jerusalén (Miqueas). La evidencia multilingüe muestra transliteración (''Ofel'') y glosas semánticas (''colina'', ''colline'', ''tumor''). El Ofel de Jerusalén era un distrito topográfico y administrativo distinto, el área de la ciudadela que Nehemías fortificó. La profecía de Isaías lo imagina abandonado, mientras que Miqueas se dirige a él como torre representativa de toda Sion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125480, 'spa', 'Tumores, plaga divina', 'Hinchazones corporales o hemorroides enviadas como juicio divino, presentes en el relato de la plaga filistea (1 Sam 5:6-12; 6:4-5) y en las maldiciones deuteronómicas (Dt 28:27). La variación Ketiv/Qeré revela la incomodidad escribal con el término. Las traducciones lo vierten uniformemente como «tumores» en español, inglés, francés y alemán, reflejando que eran protuberancias dolorosas y visibles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125481, 'spa', 'Montículo fortificado', 'Montículo fortificado o espolón que servía como acrópolis, la cresta al sur del Monte del Templo que se extiende hacia la Ciudad de David. Aparece en los relatos de reparación de Nehemías (Neh 3:26-27; 11:21) y en las noticias de fortificación del Cronista (2 Cr 27:3; 33:14). El español «el Ofel» y el inglés «the Ophel» lo tratan como topónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125482, 'spa', 'Ciudad benjaminita', 'Ciudad de Benjamín registrada en Josué 18:24 con el artículo definido, «ha-Ofni». El artículo puede indicar familiaridad o distinguirla de nombres similares. Los testimonios de la Septuaginta varían en la transliteración. La mayoría de las traducciones preservan la conjunción más el artículo y el nombre, tratándolo como designación geográfica cuya ubicación precisa sigue siendo incierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125483, 'spa', 'Párpados', 'Los párpados físicos, usados en dual como cuasi sinónimo poético de ojos. Los contextos incluyen llanto (Jer 9:18), sueño (Sal 132:4; Pr 6:4), seducción (Pr 6:25), arrogancia (Pr 30:13) y la mirada escrutadora de Dios (Sal 11:4). La célebre expresión «párpados del alba» (Job 3:9; 41:18) extiende la imagen a los primeros rayos del amanecer, como si el cielo abriera sus ojos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125493, 'spa', 'Arrojar polvo', 'En 2 Samuel 16:13 describe la acción de Simei de lanzar polvo contra David mientras lo maldecía durante la rebelión de Absalón. La conjugación Piel con acusativo cognado intensifica la acción: «arrojaba polvo sin cesar». El lanzamiento de polvo acompañaba la maldición verbal, expresando desprecio y hostilidad abierta contra el rey ungido en su momento de humillación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125494, 'spa', 'Nombre propio genealógico', 'Nombre propio que aparece en múltiples contextos genealógicos. Génesis 25:4 = 1 Crónicas 1:33 identifica a Efer como hijo de Madián. 1 Crónicas 4:17 menciona a un Efer en la línea de Judá, y 5:24 a otro en Manasés. La repetición del nombre en distintas tribus sugiere su popularidad, probablemente con el significado de ''cervatillo/becerro'' según la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125495, 'spa', 'Cervatillo o ciervo joven', 'Cría de ciervo o cervatillo empleado en la poesía erótico-pastoral del Cantar de los Cantares para evocar agilidad, belleza y vigor juvenil. El amado salta como un «cervatillo de los ciervos» (Cnt 2:9, 17; 8:14) y dos crías gemelas sirven como figura de la forma femenina (Cnt 4:5; 7:3). El término evoca la gracia delicada central al imaginario del poema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125496, 'spa', 'polvo, tierra seca', 'Sentido dominante que abarca casi todas las ocurrencias: polvo, tierra seca o suelo suelto como sustancia física. Incluye el polvo de la creación humana (Gn 2:7), el polvo de la mortalidad (Gn 3:19; Ec 3:20), el polvo arrojado en señal de duelo (Jos 7:6; Job 2:12), la tierra en purificación ritual (Lv 14:41-42; Nm 5:17) y el polvo como figura de innumerabilidad (Gn 13:16) o humillación (Gn 3:14; Mi 7:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125518, 'spa', 'polvo fino, partículas', 'Polvo fino o partículas en suspensión, un subconjunto especializado donde עָפָר no designa tierra en el suelo sino materia particulada en el aire. Dt 28:24 advierte que Dios convertirá la lluvia en ''polvo y ceniza'' que caerá como tormenta de arena devastadora. Las traducciones distinguen este sentido del polvo asentado en el suelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125521, 'spa', 'escombro, cascajo', 'Escombro o cascajo procedente de estructuras demolidas, donde עָפָר designa material de construcción derruido en vez de tierra natural. En Neh 4:10 los trabajadores lamentan la gran cantidad de escombro que dificulta la reconstrucción de los muros de Jerusalén. Las traducciones reflejan el desplazamiento de polvo natural a desechos de construcción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125524, 'spa', 'Ofrá (topónimo)', 'Nombre propio que designa ciudades israelitas, principalmente la ciudad natal de Gedeón en Manasés y un asentamiento benjaminita. La Ofrá manasita es escenario de la vocación de Gedeón: la teofanía junto a la encina (Jue 6:11), el altar de paz (Jue 6:24), el problemático efod (Jue 8:27) y su sepultura (Jue 8:32). La benjaminita aparece en Jos 18:23.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125529, 'spa', 'Efrón (hitita)', 'Efrón el hitita, propietario del campo y la cueva de Macpela cerca de Hebrón. Génesis 23:8–17 relata la negociación de Abraham para adquirir el lugar de sepultura: Efrón ofreció inicialmente el campo como regalo antes de fijar un precio de cuatrocientos siclos de plata. Las catorce apariciones se concentran en Génesis 23, 25:9, 49:29–30 y 50:13.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125532, 'spa', 'Efraín (ciudad)', 'Una ciudad (a veces vocalizada Efraín o Efrón) capturada por el rey Abías de Judá del reino del norte. En 2 Crónicas 13:19 aparece junto a Betel y Jesaná como poblaciones tomadas tras la victoria de Abías sobre Jeroboam. Esta única aparición se refiere probablemente a una localidad cercana a Betel, posiblemente idéntica a Ofra o la Efraín mencionada en otros textos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125535, 'spa', 'árbol, árbol vivo', 'Árbol vivo, en pie, individual o colectivamente, o como especie determinada. Los árboles edénicos de la vida y del conocimiento (Gn 2:9; 3:3) anclan la palabra teológicamente, mientras que Jue 9:8 personifica los árboles en la fábula de Jotam. Jer 17:8 y Sal 1:3 emplean el árbol plantado junto a aguas como imagen quintaesencial del justo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125536, 'spa', 'madera, material', 'Madera como material procesado para construcción, carpintería y artesanía: tablas, vigas y tablones. Las instrucciones del tabernáculo dominan este sentido: madera de acacia para el arca (Éx 25:10), la mesa (25:23) y los bastidores (26:15). El templo de Salomón requiere igualmente grandes cantidades de madera (1 R 5-6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125543, 'spa', 'leña, combustible', 'Madera recogida o destinada como combustible: leña y astillas para el fuego. El relato de la Aqedá está saturado de este sentido: Abraham parte la leña, Isaac la carga y se dispone sobre el altar (Gn 22:3, 6, 7, 9). Las instrucciones levíticas sobre ofrendas especifican repetidamente la disposición de la leña sobre el fuego del altar (Lv 1:7-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125546, 'spa', 'madero, patíbulo', 'Estaca, poste o madero vertical de gran tamaño destinado a la ejecución pública o exhibición de un cadáver. El libro de Ester concentra las nueve ocurrencias: Amán erige un madero de cincuenta codos para Mardoqueo (Est 5:14; 7:9-10). Este sentido punitivo-exhibitivo porta connotaciones de vergüenza pública y reversal divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125547, 'spa', 'asta, mango de arma', 'Asta o mango de madera de un arma, particularmente una lanza. 1 S 17:7 describe el asta de la lanza de Goliat como gruesa ''como un rodillo de telar'', convirtiendo el עֵץ en medida del poder aterrador del gigante. Otras ocurrencias en listas de materiales (Éx 25:5; Lv 14:4, 49) probablemente se refieren a varillas de cedro para purificación ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125550, 'spa', 'palo, vara', 'Pieza de madera labrada que funciona como palo, vara o bastón. Los dos palos simbólicos de Ezequiel que representan a Judá e Israel (Ez 37:16-20) son los ejemplos de mayor carga teológica. Lm 4:8 emplea la comparación ''su piel se ha resecado sobre sus huesos, se ha vuelto seca como un palo'' para describir Jerusalén devastada por el asedio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125589, 'spa', 'tallos de lino', 'Ocurrencia única en Jos 2:6 donde עֵץ parece designar tallos de lino dispuestos sobre el techo de Rajab. Las traducciones multilingües identifican uniformemente el material como lino y no como madera. Puede reflejar un uso agrícola especializado (tallos leñosos del lino) o una anomalía textual, pero el contexto de secar lino en una azotea es inequívoco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125625, 'spa', 'Afligirse, sentir pesar', 'Aflicción emocional intransitiva: el sujeto experimenta pesar, angustia o profundo desagrado. Es el sentido dominante, presente en las formas Nifal, Hitpael y participio pasivo Qal. Dios «se dolió en su corazón» (Gn 6:6), Jonatán «se entristeció» por David (1 Sam 20:34) y Sion es llamada «herida de espíritu» (Is 54:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125628, 'spa', 'Agraviar, contristar', 'Aflicción causativa: el sujeto causa dolor o pesar a otro. El padre de David «no lo contristó» (1 Re 1:6), Jabes ora para que el mal no «me aflija» (1 Cr 4:10) e Israel «contristó a su Espíritu Santo» (Is 63:10). El español emplea «contristar» y «entristecer», confirmando la lectura emotivo-causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125629, 'spa', 'Torcer, distorsionar', 'Torcer, distorsionar o tergiversar: un uso Piel semánticamente distinto, aplicado a palabras en vez de emociones. En Sal 56:5 los enemigos «tuercen» las palabras de David. El español «tuercen» se alinea con este sentido concreto, no emocional, de distorsión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125631, 'spa', 'Ser herido, lastimarse', 'Sufrir daño físico, distinto de la aflicción emocional. En Ecl 10:9 quien parte piedras «se lastimará» con ellas. El español «se lastimará» confirma que se trata de daño corporal y no de pesar, marcando este como el único sentido de dolor físico de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125639, 'spa', 'Voz angustiada', 'En Daniel 6:20 describe la cualidad adolorida de la voz del rey Darío al llamar a Daniel en el foso de los leones. La angustia emocional del rey por el destino de Daniel se manifiesta en su tono vocal. El participio pasivo indica un estado de aflicción profunda causada por el temor y la preocupación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125641, 'spa', 'Trabajo penoso, afán', 'Trabajo oneroso, esfuerzo productivo o labor agotadora: la faena que ocupa y fatiga a la persona. Prov 14:23 enseña que «en todo afán hay provecho», Sal 127:2 habla del «pan de los afanes» ganado con esfuerzo ansioso, y Prov 5:10 advierte que los trabajos propios pueden enriquecer a extraños.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125643, 'spa', 'Dolor, pena, sufrimiento', 'Sufrimiento físico o emocional, pesar o agravio: la dimensión afectiva de la raíz. En Gen 3:16, la primera aparición en las Escrituras, Dios multiplica el dolor de Eva en el parto. Prov 15:1 lo emplea para la herida emocional: la palabra áspera provoca dolor (דְּבַר־עֶצֶב), en contraste con la respuesta suave que aplaca la ira.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125646, 'spa', 'Vasija despreciada', 'En Jeremías 22:28 se pregunta retóricamente si Conías es una vasija despreciada y rota que nadie desea. La metáfora recurre a la imagen alfarera: un rey reducido a un cacharro rechazado. El término enfatiza la condición de objeto moldeado, haciendo la comparación especialmente incisiva al señalar que incluso como pieza artesanal, Conías carece de valor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125647, 'spa', 'Dolor o sufrimiento', 'Tres apariciones abarcando dolor de parto, daño moral y sufrimiento del exilio. La evidencia multilingüe muestra traducción consistente de ''dolor/dolor'', con variación preposicional. La etimología de 1 Crónicas conecta el nombre Jabes (''él causa dolor'') con la experiencia de su madre. El ''camino doloroso'' del Salmo 139 se refiere a cualquier senda malvada que trae daño—el salmista pide a Dios que lo guíe en la dirección opuesta. Isaías 14:3 promete el fin del dolor del exilio babilónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125648, 'spa', 'Ídolo fabricado', 'En Isaías 48:5 Dios dice que declaró los eventos futuros de antemano para que Israel no dijera ''mi ídolo los hizo''. El sufijo posesivo ''mi ídolo'' revela la tendencia de Israel a atribuir la acción divina a sus imágenes talladas. El término, derivado de la raíz que significa formar o moldear, subraya que los ídolos son meros objetos manufacturados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125649, 'spa', 'Ídolos, imágenes talladas o fundidas adoradas como dioses falsos, siempre en plu', 'Ídolos, imágenes talladas o fundidas adoradas como dioses falsos, siempre en plural y condenadas de forma constante. Oseas emplea el término para denunciar la idolatría de Efraín (4:17; 8:4; 13:2), especificando a menudo su composición material de plata y oro. Los Salmos se burlan de ellos como artefactos humanos sin vida (115:4; 135:15), mientras que los textos proféticos los emparejan con términos paralelos como גִּלּוּלִים (''bolas de estiércol'') en Jeremías 50:2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125660, 'spa', 'Trabajadores oprimidos', 'En Isaías 58:3 se refiere a los obreros o trabajadores a quienes el pueblo oprime mientras practica el ayuno. Dios condena la hipocresía de la observancia religiosa combinada con la injusticia social hacia quienes laboran para ellos. El sufijo ''vuestros obreros'' subraya la relación entre empleadores y trabajadores, agravando la denuncia de la opresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125661, 'spa', 'Dolor y trabajo penoso', 'Tres ocurrencias, todas en Génesis 3-5 describiendo la experiencia humana posterior a la Caída. La evidencia multilingüe traduce ''dolor/pena/toil/douleur/Mühsal'', capturando las dimensiones de sufrimiento y labor. Génesis 3:16 se enfoca en el dolor del parto, mientras que 3:17 enfatiza el trabajo penoso agrícola. Génesis 5:29 anticipa alivio del trabajo de cultivar la tierra maldita. La palabra representa la condición humana fundamental bajo la maldición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125662, 'spa', 'Dolor y aflicción', 'Dolor físico o emocional, herida y tristeza que surgen del sufrimiento, la maldad o la idolatría. En Job 9:28 denota la totalidad de la angustia corporal y existencial; en Sal 147:3, Dios sana esas heridas. Prov 15:13 contrapone la «tristeza del corazón» al corazón alegre. El término cubre un espectro que va desde la lesión concreta hasta el pesar espiritual más profundo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125663, 'spa', 'Cerrar los ojos', 'En Proverbios 16:30 describe a quien cierra sus ojos para tramar perversidades. El participio activo indica un hábito de cerrar los ojos, sugiriendo la exclusión intencional de la visión moral para concentrarse en planes malvados. El paralelo con ''apretar los labios'' señala una maldad deliberada y calculada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125664, 'spa', 'Espinazo sacrificial', 'En Levítico 3:9, se refiere al espinazo o específicamente al hueso sacro cercano a la cola grasa del animal sacrificial. La cola grasa era característica de las razas ovinas del Cercano Oriente, y se requería un conocimiento anatómico preciso para realizar correctamente el sacrificio. El término señala el punto vertebral de referencia para la separación de la grasa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125665, 'spa', 'Árboles para asedio', 'En Jeremías 6:6, esta forma probablemente debe leerse como «sus árboles» (con sufijo), refiriéndose a los árboles de Jerusalén que deben talarse para construir obras de asedio. El pasaje presenta una imagen de juicio en la que se cortan los árboles con fines militares. Las variantes manuscritas, incluidas la Septuaginta, la Siríaca, la Vulgata y el Targum, apoyan la lectura con sufijo posesivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125666, 'spa', 'Consejo o recomendación — el sentido interpersonal ordinario', 'Consejo o recomendación — el sentido interpersonal ordinario: orientación ofrecida por una persona a otra. El consejo de Ahitofel (2 S 15:31, 16:23), el consejo de los ancianos frente al de los jóvenes (1 R 12:8-14) y el consejo que recibe Esdras (Esd 10:3). Proverbios 1:25 personifica a la Sabiduría lamentando que ''desechasteis todo consejo mío'', dando a la palabra su máxima dimensión sapienticial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125676, 'spa', 'Consejos, maquinaciones o tramas — la forma plural que a menudo conlleva una con', 'Consejos, maquinaciones o tramas — la forma plural que a menudo conlleva una connotación negativa de intrigas y deliberación hostil. Los enemigos frustran planes (Esd 4:5, Neh 4:15), el salmista lucha con ''consejos en mi alma'' (Sal 13:2), y las rebeliones de Israel se multiplican por sus propias maquinaciones (Sal 106:43). Preserva el matiz conspirativo de quienes se confabulan contra otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125677, 'spa', 'Plan, propósito o designio soberano — el sentido que eleva el consejo de un simp', 'Plan, propósito o designio soberano — el sentido que eleva el consejo de un simple parecer humano a una intención determinada, especialmente el decreto inalterable de Dios. ''El consejo de Yahvé permanece para siempre'' (Sal 33:11); ''Mi consejo permanecerá'' (Is 46:10); ''Yahvé de los ejércitos lo ha determinado, ¿quién lo anulará?'' (Is 14:26-27). Proverbios 19:21 traza el contraste: ''Muchos son los planes en el corazón del hombre, pero el consejo de Yahvé permanecerá''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125695, 'spa', 'Una ocurrencia singular en Isaías 19', 'Una ocurrencia singular en Isaías 19:11 donde la forma constructa ''consejeros de'' funciona como una designación casi concreta para quienes dan consejo — los sabios asesores de Faraón. Las traducciones pasan del sustantivo abstracto al sustantivo agentivo, reflejando cómo la cadena constructa orienta la palabra hacia la persona y no hacia la actividad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125708, 'spa', 'Poderoso, fuerte o robusto — describiendo pueblos, naciones, reyes o fuerzas que', 'Poderoso, fuerte o robusto — describiendo pueblos, naciones, reyes o fuerzas que poseen un formidable poder militar o político. Faraón admite que Israel es עָצוּם מִמֶּנּוּ (''más fuerte que nosotros,'' Éx 1:9), y Dios promete desposeer naciones גְּדֹלִים וַעֲצוּמִים (Dt 4:38). La forma sustantivada en Sal 135:10 designa ''reyes poderosos.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125712, 'spa', 'Numeroso, vasto o grande en extensión — enfatizando la cantidad pura más que la ', 'Numeroso, vasto o grande en extensión — enfatizando la cantidad pura más que la fuerza. Amós 5:12 condena las עֲצֻמִים (''numerosas'') transgresiones de Israel, y Sal 35:18 contempla la alabanza entre un עַם עָצוּם (''pueblo numeroso''). La superposición con el sentido 1 es natural, ya que los grandes números implican poder, pero aquí el enfoque recae sobre la magnitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125722, 'spa', 'Ezión-guéber (puerto)', 'Ciudad portuaria de Ezión-guéber (עֶצְיוֹן גֶּבֶר), en la cabecera del Golfo de Áqaba, cerca de Elat. Aparece primero como campamento durante el éxodo (Núm 33:35-36; Deut 2:8). Bajo Salomón se convirtió en base naval para el comercio con Ofir (1 Re 9:26; 2 Cr 8:17). Josafat intentó revivir esta empresa marítima, pero sus barcos naufragaron (1 Re 22:48).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125729, 'spa', 'Pereza culpable', 'En Jueces 18:9, los espías dicen a sus compañeros danitas «no seáis perezosos para ir» a poseer la buena tierra. La prohibición advierte contra la pereza o la vacilación cuando se presenta una oportunidad. El contexto hace que la indolencia sea censurable: han visto la bondad de la tierra y deben actuar con determinación. La raíz verbal enfatiza una inactividad deliberada y reprochable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125730, 'spa', 'El perezoso', 'Persona crónicamente perezosa u holgazana, empleada como figura arquetípica en la instrucción sapiencial. Las catorce apariciones se hallan en Proverbios, donde el ʿatsel sirve de ejemplo negativo: se le exhorta a aprender de la hormiga (Prov 6:6, 9), se lo describe como molestia para quien lo envía (10:26), desea sin obtener nada (13:4; 21:25) y halla su camino obstruido por espinos (15:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125734, 'spa', 'Ociosidad improductiva', 'En Proverbios 31:27, describe «el pan de la ociosidad» que la mujer virtuosa no come. La frase emplea «pan» para representar el sustento o modo de vida, creando la imagen de quien consume sin producir, viviendo en perezosa inactividad. Ella rechaza esta ociosidad y trabaja productivamente. El versículo elogia el compromiso constante con el trabajo y la diligencia como virtud doméstica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125735, 'spa', 'Ser fuerte o poderoso en el Qal', 'Ser fuerte o poderoso en el Qal: describe una fuerza inherente o un crecimiento en poder. Isaac le dice a Abimelec ''te has hecho demasiado poderoso para nosotros'' (Gn 26:16), y las visiones de Daniel usan este sentido reiteradamente para imperios que se engrandecen (Dn 8:8, 24; 11:23). Las traducciones al español ''son poderosos'' y ''se fortalecerá'' marcan consistentemente un poderío personal o nacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125737, 'spa', 'Ser numeroso o vasto en el Qal', 'Ser numeroso o vasto en el Qal: expresa abundancia más que fuerza. El salmista exclama que sus enemigos ''son más que los cabellos de mi cabeza'' (Sal 69:4) y que los pensamientos de Dios superan en número a la arena (Sal 139:17). El español distingue este sentido claramente con ''se multiplicaron'' y ''fueron numerosos'', mientras que Jeremías lo usa para transgresiones que se multiplican (Jer 5:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125740, 'spa', 'Quebrantar huesos (Piel)', 'Quebrantar huesos (Piel): un denominativo que significa quebrantar o roer los huesos, derivado del sustantivo עֶצֶם (hueso). Aparece únicamente en Jeremías 50:17, donde describe a Nabucodonosor ''quebrando los huesos'' de Israel, una metáfora vívida de devorar a un pueblo conquistado que conecta etimológicamente este sentido con el núcleo físico de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125744, 'spa', 'Hacer fuerte (Hifil)', 'Hacer fuerte (Hifil): el causativo, hacer fuerte o hacer que alguien llegue a ser poderoso. En el Salmo 105:24, Dios ''hizo a su pueblo más fuerte que sus adversarios'', un acto de empoderamiento divino. El español ''lo hizo más fuerte'' marca claramente la agencia causativa: no es un crecimiento propio del pueblo, sino Dios fortaleciéndolo activamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125749, 'spa', 'hueso(s), parte esquelética', 'Hueso o huesos físicos de una persona o animal: el sentido literal dominante con 105 ocurrencias. Abarca los huesos de José trasladados desde Egipto (Éx 13:19; Jos 24:32), los huesos de los muertos (2 S 21:12), los huesos como sinécdoque del cuerpo en aflicción (Sal 22:14; 31:10) y la fórmula de parentesco ''hueso de mis huesos'' que expresa consanguinidad (Gn 2:23; Jue 9:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125757, 'spa', 'ese mismo, aquel preciso', 'Marcador enfático de identidad temporal: ''ese mismo, aquel preciso día'', con 17 ocurrencias, exclusivamente en la frase constructa בְּעֶצֶם הַיּוֹם (הַזֶּה), literalmente ''en el hueso/sustancia de este día''. Señala precisión temporal y peso narrativo en momentos críticos: el inicio del Diluvio (Gn 7:13), la circuncisión de Abraham (Gn 17:23, 26), el Éxodo (Éx 12:17, 41) y la entrada en Canaán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125770, 'spa', 'sustancia, esencia', 'Sustancia, cuerpo, plenitud o naturaleza esencial: 4 ocurrencias en las que עֶצֶם se extiende figuradamente para significar la materia o esencia fundamental de algo. En Éx 24:10 los ancianos ven bajo los pies de Dios ''como el עֶצֶם del cielo en pureza'': la sustancia misma del firmamento. En Job 21:23 uno muere ''en el עֶצֶם de su plenitud'': en la plena sustancia de su prosperidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125811, 'spa', 'Ciudad tribal en el Néguev', 'Tres ocurrencias en listas de asignación tribal: una a Judá, dos a Simeón. La evidencia multilingüe muestra transliteración con conjunciones, ya que aparecen en listas catalogadas. La doble asignación refleja la situación única de Simeón, disperso dentro del territorio de Judá en lugar de tener un área tribal contigua. La referencia en Crónicas dentro de las ciudades genealógicas de Simeón confirma la conexión simeonita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125812, 'spa', 'Poder o estructura corporal', 'Tres ocurrencias con ''poder'' en Deuteronomio y Job, ''estructura'' en Salmos. La evidencia multilingüe muestra el rango semántico: ''poder/might/Knochen (huesos)/frame''. El contexto de Deuteronomio advierte contra la autoatribución orgullosa de la fuerza. La queja de Job invierte la misma idea: la mano poderosa de Dios se ha convertido en instrumento de sufrimiento en lugar de bendición. El uso del Salmo 139 es tierno, describiendo la estructura no nacida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125813, 'spa', 'Fuerza vigorosa y abundante', 'Tres ocurrencias describiendo provisión divina de fuerza, poder hechicero y alianzas imperiales. La evidencia multilingüe traduce ''strength/fortaleza/vigueur/puissance'', capturando la dimensión de poder robusto. El uso de Isaías 40 es alentador: Dios multiplica la fuerza para el cansado. El uso de Isaías 47 es irónico: el gran poder hechicero de Babilonia no prevendrá el desastre. La pregunta retórica de Nahúm sugiere que ningún poder humano es infinito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125814, 'spa', 'Argumento forense', 'En Isaías 41:21, Dios convoca a las deidades paganas a presentar sus «defensas», los argumentos más convincentes que puedan ofrecer para justificar su legitimidad. El término tiene peso jurídico, como en un tribunal donde el acusado exhibe su mejor caso. La raíz verbal asociada a la fuerza subraya que se exigen pruebas contundentes, no meras excusas, en este drama retórico de juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125815, 'spa', 'Marcador fronterizo meridional', 'Tres ocurrencias, todas en descripciones de fronteras. La evidencia multilingüe muestra transliteración con marcadores direccionales (''hacia'', ''desde'', ''Azmoná''). Números 34 da la descripción fronteriza en instrucción divina, mientras Josué 15 registra su implementación en la asignación real de Judá. La forma direccional Azmoná enfatiza movimiento hacia el sitio mientras procede la frontera. Como punto fronterizo, representa el límite extremo del territorio prometido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125817, 'spa', 'Describe a personas encerradas como prisioneros o cautivos, frecuentemente como ', 'Describe a personas encerradas como prisioneros o cautivos, frecuentemente como participio pasivo עָצוּר. La fórmula ''cautivo y libre'' (1 R 14:10; Dt 32:36) se convirtió en un merismo para designar a toda persona. El énfasis recae sobre la restricción involuntaria de movimiento y libertad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125818, 'spa', 'El nifal pasivo registra plagas y desastres siendo detenidos, memorablemente cua', 'El nifal pasivo registra plagas y desastres siendo detenidos, memorablemente cuando Aarón se interpuso entre los vivos y los muertos y la plaga ''fue detenida'' (Nm 16:48-50). El sentido enfatiza el cese provocado por una intervención externa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125819, 'spa', 'Retener o conservar la posesión de algo, incluyendo fuerza o recursos', 'Retener o conservar la posesión de algo, incluyendo fuerza o recursos. Daniel confiesa dos veces que ''no retuvo fuerza'' (Dn 10:8, 16), mientras en 1 Cr 29:14 David pregunta quién tiene la capacidad de retener lo suficiente para ofrecer voluntariamente. El enfoque está en la capacidad interna de mantener lo que se posee.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125824, 'spa', 'Restricción activa de una persona o fuerza para impedirle avanzar', 'Restricción activa de una persona o fuerza para impedirle avanzar. En Gn 16:2 Sarai dice que Dios la ha ''restringido de dar a luz,'' y en 1 S 9:17 Dios dice a Samuel que Saúl ''gobernará'' al pueblo. Capta el sentido de frenar o contener la acción o el poder de otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125825, 'spa', 'Dios cerrando los cielos o el vientre, impidiendo la lluvia o la fertilidad', 'Dios cerrando los cielos o el vientre, impidiendo la lluvia o la fertilidad. Génesis 20:18 emplea el infinitivo absoluto enfático para recalcar que el SEÑOR había ''ciertamente cerrado'' todo vientre. El agente es casi siempre Dios, marcando este uso como teológicamente cargado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125830, 'spa', 'Detener a una persona para impedirle marcharse', 'Detener a una persona para impedirle marcharse. En Jueces 13:15-16 Manoa insta al ángel a quedarse, y en 2 R 17:4 Oseas es arrestado. A diferencia del sentido 1 (encarcelamiento formal), este describe la prevención circunstancial de una partida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125840, 'spa', 'Una extensión idiomática que significa ''tener poder'' o ''ser capaz,'' como en Job ', 'Una extensión idiomática que significa ''tener poder'' o ''ser capaz,'' como en Job 29:9 donde los príncipes fueron impedidos de hablar, y 1 S 21:6 donde los jóvenes habían sido apartados de las mujeres. Este sentido tiende un puente entre la contención física y la capacidad abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125858, 'spa', 'Restricción o riqueza', 'Jueces 18:7 emplea este término en una frase tan oscura que incluso los traductores antiguos discreparon. La tradición hebrea lo lee como ''restricción'' o ''control'', posiblemente aludiendo a la autoridad gubernamental. Las versiones griega y latina, en cambio, vieron ''riqueza''. Los estudiosos modernos sospechan corrupción textual, proponiendo que la palabra combina dos raíces hebreas distintas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125859, 'spa', 'Restricción opresiva', 'El término denota restricción violenta o fuerza opresiva. En Isaías 53:8, el siervo es removido ''de la opresión y del juicio'', sugiriendo tanto coerción social como condena legal. Salmo 107:39 probablemente lo usa para angustia general, mientras que Proverbios 30:16 emplea ''restricción del vientre'' como forma poética de describir esterilidad junto al Seol y la tierra estéril—cosas nunca satisfechas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125860, 'spa', 'Asamblea solemne', 'Asamblea sagrada formalmente convocada, que típicamente marca el día de clausura de una festividad mayor de peregrinación. Prescrita para el octavo día de Sucot (Lv 23:36; Nm 29:35) y el último día de la semana de Pascua (Dt 16:8). Observada en rededicaciones del templo (2 Cr 7:9) y renovaciones del pacto (Neh 8:18). Jehú convoca una cínicamente para atrapar a los adoradores de Baal (2 R 10:20). Los profetas la emplean como piedra de toque de la sinceridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125869, 'spa', 'Suplantar y engañar', 'Asir el talón, suplantar o aventajar con astucia, abarcando tanto el acto literal del relato de nacimiento (Os 12:3, evocando Gn 25:26) como el sentido figurado de socavar con engaño (Gn 27:36; Jer 9:4). El juego etimológico entre el verbo y el nombre יַעֲקֹב (Jacob) es central. Job 37:4 amplía el campo semántico hacia la idea de retener o contener.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125870, 'spa', 'Porque, a causa de', 'Conjunción causal: «porque, a causa de», que introduce el fundamento de una promesa o un juicio. Dios promete a Abraham «por cuanto obedeciste mi voz» (Gn 22:18; 26:5), Moisés advierte «por cuanto no obedecisteis» (Dt 8:20) y Caleb recibe su heredad «por cuanto siguió plenamente al SEÑOR» (Nm 14:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125871, 'spa', 'Fin, resultado', 'Sustantivo temporal-terminal: «fin, resultado», que denota el punto final de una acción. El salmista pide guardar los estatutos de Dios «hasta el fin» (Sal 119:33) y se compromete a la obediencia «hasta el fin, para siempre» (Sal 119:112). El paralelo hebreo la-ʿad («para siempre») confirma este sentido temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125872, 'spa', 'Recompensa, galardón', 'Recompensa o galardón: el fruto de la conducta justa. Guardar los mandamientos de Dios produce «gran recompensa» (Sal 19:11), y «el resultado de la humildad y el temor del SEÑOR son riquezas, honra y vida» (Prov 22:4). El cognado árabe ʿaqib confirma el patrón semítico de «la consecuencia se convierte en recompensa».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125877, 'spa', 'talón (parte del cuerpo)', 'El talón literal del pie humano. Génesis 25:26 describe la mano de Jacob agarrando el talón de Esaú al nacer, acto que le dio su nombre. En Génesis 3:15, la serpiente hiere el talón de la simiente de la mujer, y en Job 18:9 una trampa atrapa al malvado por el talón. ''Calcáñar'' y ''talón'' designan específicamente esta parte anatómica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125878, 'spa', 'huella, rastro, pisada', 'Extensión metafórica del talón hacia la impresión que deja: huellas, rastros o vestigios. El Salmo 77:19 celebra que las pisadas de Dios por el Mar Rojo fueron inescrutables, mientras que el Salmo 89:51 habla de enemigos burlándose de las pisadas del ungido de Dios. ''Huellas'' y ''pisadas'' expresan fielmente esta lectura figurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125881, 'spa', 'casco (de animal)', 'Aplicado a la anatomía animal: los cascos de caballos resonando en batalla. Jueces 5:22 usa el plural para describir el galope atronador (''entonces los cascos de los caballos golpearon''). ''Cascos'' corresponde con precisión a esta extensión zoológica del talón humano al casco equino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125882, 'spa', 'retaguardia', 'Uso figurado militar en Josué 8:13 que designa la retaguardia o la parte posterior de una formación militar: el ''talón'' de la columna en marcha. ''Retaguardia'' hace explícita la metáfora espacial-militar: la última parte del cuerpo se convierte en la última parte del ejército.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125889, 'spa', 'Suplantadores engañosos', 'El Salmo 49:5 habla de ''mis suplantadores'': quienes buscan ventaja mediante el engaño, como Jacob hizo con Esaú, cuyo nombre se vincula a ''talón''. El salmista se siente rodeado por sus maquinaciones. Las lenguas afines confirman el sentido de desplazar a otro mediante la astucia, combinando la imagen del talón con la suplantación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125891, 'spa', 'Terreno escarpado', 'En Isaías 40:4, esta palabra describe un terreno empinado y accidentado que dificulta el tránsito. El profeta declara que tales lugares serán aplanados cuando Dios venga. Las lenguas cognadas lo confirman: el árabe tiene ''sendero montañoso difícil'', el etiópico ''colina''. El español traduce ''lo torcido'', fusionando el sentido físico con la metáfora moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125892, 'spa', 'Astucia insidiosa', 'En 2 Reyes 10:19, Jehú emplea esta ''astucia'' o ''artimaña'' para engañar a los adoradores de Baal, haciéndoles creer que asisten a un gran sacrificio cuando en realidad serán exterminados. La raíz hebrea sugiere maquinación solapada. La narrativa es moralmente compleja: la argucia de Jehú sirve para eliminar la idolatría, pero el método es puro engaño calculado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125893, 'spa', 'Atar firmemente', 'Génesis 22:9 registra el terrible momento en que Abraham ''ató'' a Isaac sobre el altar. El verbo significa sujetar los miembros entre sí, quizá con los brazos a la espalda o las piernas dobladas. Las lenguas semíticas afines confirman este sentido de atar con firmeza. Los Targumes asocian la raíz con arrodillarse, evocando la postura de la víctima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125894, 'spa', 'Rayado, listado', 'Rayado o listado en el pelaje, usado exclusivamente para describir ovejas y cabras en el relato de Jacob y Laban (Gn 30:35-40; 31:8, 10, 12). El adjetivo designa animales con bandas o lineas visibles en su lana o piel, distinguiendolos de los moteados (נָקֹד) y pintados (טָלוּא). La estrategia divinamente guiada de Jacob produjo estos animales rayados como su salario legitimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125896, 'spa', 'Opresión aplastante', 'En el Salmo 55:3, esta palabra aramea describe la «presión» u «opresión» que el salmista siente por parte de adversarios impíos. El término sugiere una fuerza que comprime y causa angustia. Algunos estudiosos, al notar la estructura paralela con «voz», proponen enmendar el texto a «clamor» (צְעָקַת), lo que daría mejor sentido poético: «voz... clamor de los impíos».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125897, 'spa', 'Acub (nombre propio)', 'Nombre propio que significa aproximadamente ''vigilante'' o ''guardado'', aplicado a al menos seis individuos distintos en la literatura postexilica. Entre ellos figuran un hijo de Elioenai en la linea davidica (1 Cr 3:24), varios porteros levitas que custodiaban los almacenes del Templo (1 Cr 9:17; Neh 11:19; 12:25), jefes de familias repatriadas del exilio (Esd 2:42 = Neh 7:45) y un levita que asistio a Esdras en la lectura publica de la Ley (Neh 8:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125899, 'spa', 'Justicia pervertida', 'En Habacuc 1:4, este participio pasivo describe la justicia como «pervertida», literalmente torcida o deformada. La raíz aparece en diversas lenguas semíticas con el sentido de doblar o torcer. La queja del profeta es que los impíos rodean al justo, de modo que la justicia no puede salir recta sino deformada, como un metal golpeado hasta tomar una forma incorrecta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125901, 'spa', 'Serpiente sinuosa', 'En Isaías 27:1, este adjetivo describe a Leviatán como «tortuoso» o «sinuoso», evocando la imagen de una serpiente que se enrosca y ondula por el mar. La tradición hebrea conserva el sentido de algo que se mueve en curvas, no en línea recta. Algunos eruditos ven una referencia a la constelación Draco, cuya cola se enrosca alrededor de la estrella polar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125902, 'spa', 'Nombre propio edomita', 'Acán es un nombre edomita en Génesis 36:27, enumerado entre los descendientes de Seir el horeo. En la genealogía paralela de 1 Crónicas 1:42 se le llama Jaacán. Las Escrituras mencionan también «Bene-Jaacán» (los hijos de Jaacán) como topónimo durante las peregrinaciones de Israel por el desierto. Las versiones griegas ofrecen diversas transliteraciones, evidenciando cierta fluidez en la pronunciación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125904, 'spa', 'Desjarretar animales', 'Cortar los tendones de las patas de un animal (especialmente caballos o bueyes) para lisiarlo permanentemente. Se emplea en contextos militares donde los caballos de carros capturados son inutilizados por mandato divino (Jos 11:6, 9; 2 S 8:4 = 1 Cr 18:4), y una vez para describir violencia gratuita contra ganado (Gn 49:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (125906, 'spa', 'Vástago familiar', 'Levítico 25:47 se refiere a «un vástago de la familia del extranjero», un miembro o rama del clan extendido. El término deriva de la raíz, sugiriendo alguien que ha brotado del árbol genealógico, tal vez un pariente lejano o miembro de una rama secundaria. En el contexto legal de la redención de un israelita esclavizado, cualquier persona conectada a la familia puede actuar como redentor.');